"""Vector store implementations.

Primary backend: ``TfidfVectorStore`` -- a deterministic, dependency-light
semantic store built on TF-IDF weighted token vectors and cosine similarity.
It is fully self-contained (NumPy only) so the RAG system runs offline.

Optional backend: ``ChromaVectorStore`` wrapper around ChromaDB (used when
``RAGConfig.backend == "chroma"`` and chromadb is installed).
"""
from __future__ import annotations

import math
import re
from collections import Counter
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Sequence

import numpy as np

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> List[str]:
    """Lowercase alphanumeric tokenization with minimal noise filtering."""
    return _TOKEN_RE.findall(text.lower())


@dataclass
class StoredChunk:
    """A chunk together with its metadata, as held by the vector store."""

    id: str
    text: str
    metadata: Dict[str, object] = field(default_factory=dict)


class TfidfVectorStore:
    """In-memory TF-IDF vector store with cosine similarity search."""

    def __init__(self) -> None:
        self._chunks: Dict[str, StoredChunk] = {}
        self._idf: Dict[str, float] = {}
        self._vectors: Dict[str, np.ndarray] = {}
        self._vocab: List[str] = []
        self._vocab_index: Dict[str, int] = {}

    # ------------------------------------------------------------------ #
    # Indexing                                                            #
    # ------------------------------------------------------------------ #
    def add(self, chunk: StoredChunk) -> None:
        self._chunks[chunk.id] = chunk
        self._rebuild()

    def add_many(self, chunks: Sequence[StoredChunk]) -> None:
        for chunk in chunks:
            self._chunks[chunk.id] = chunk
        self._rebuild()

    def _rebuild(self) -> None:
        """(Re)build the vocabulary, IDF weights and TF-IDF vectors."""
        df: Counter = Counter()
        tf: Dict[str, Counter] = {}

        for chunk in self._chunks.values():
            tokens = tokenize(chunk.text)
            counts = Counter(tokens)
            tf[chunk.id] = counts
            for term in counts:
                df[term] += 1

        n_docs = max(1, len(self._chunks))
        # Smooth IDF: log(1 + N / (1 + df)) + 1 to avoid zero weights.
        self._idf = {
            term: math.log(1.0 + n_docs / (1.0 + freq)) + 1.0
            for term, freq in df.items()
        }
        self._vocab = sorted(self._idf)
        self._vocab_index = {term: i for i, term in enumerate(self._vocab)}

        dim = len(self._vocab)
        self._vectors = {}
        for chunk_id, counts in tf.items():
            vec = np.zeros(dim, dtype=np.float64)
            norm = 0.0
            for term, freq in counts.items():
                idx = self._vocab_index[term]
                w = freq * self._idf[term]
                vec[idx] = w
                norm += w * w
            if norm > 0:
                vec /= math.sqrt(norm)
            self._vectors[chunk_id] = vec

    # ------------------------------------------------------------------ #
    # Query                                                               #
    # ------------------------------------------------------------------ #
    def query_vector(self, text: str) -> np.ndarray:
        """Return the L2-normalized TF-IDF vector for a raw query string."""
        counts = Counter(tokenize(text))
        vec = np.zeros(len(self._vocab), dtype=np.float64)
        norm = 0.0
        for term, freq in counts.items():
            idx = self._vocab_index.get(term)
            if idx is None:
                continue
            w = freq * self._idf.get(term, 0.0)
            vec[idx] = w
            norm += w * w
        if norm > 0:
            vec /= math.sqrt(norm)
        return vec

    def similarity(self, query: str, chunk_id: str) -> float:
        qv = self.query_vector(query)
        cv = self._vectors.get(chunk_id)
        if cv is None or qv.size == 0:
            return 0.0
        return float(np.dot(qv, cv))

    def similarity_scores(self, query: str) -> Dict[str, float]:
        qv = self.query_vector(query)
        if qv.size == 0:
            return {cid: 0.0 for cid in self._vectors}
        out: Dict[str, float] = {}
        for cid, cv in self._vectors.items():
            out[cid] = float(np.dot(qv, cv))
        return out

    def get(self, chunk_id: str) -> Optional[StoredChunk]:
        return self._chunks.get(chunk_id)

    def all_chunks(self) -> List[StoredChunk]:
        return list(self._chunks.values())

    def __len__(self) -> int:
        return len(self._chunks)


# ---------------------------------------------------------------------- #
# Optional ChromaDB backend                                               #
# ---------------------------------------------------------------------- #
class ChromaVectorStore:
    """Thin wrapper around ChromaDB.

    Requires ``chromadb`` and an embedding function. If no embedding function
    is supplied, a deterministic hashing embedding is used so the wrapper
    still works offline (semantic quality is lower than the TF-IDF backend;
    it exists mainly to demonstrate pluggable vector DB integration).
    """

    def __init__(self, collection_name: str = "metadata_rag", persist_dir: str = ".chroma_db"):
        import chromadb

        self._client = chromadb.PersistentClient(path=persist_dir)
        self._collection = self._client.get_or_create_collection(
            name=collection_name,
            metadata={"hnsw:space": "cosine"},
            embedding_function=HashingEmbeddingFunction() if False else None,
        )
        self._hasher = HashingEmbeddingFunction()

    def add_many(self, chunks: Sequence[StoredChunk]) -> None:
        ids = [c.id for c in chunks]
        docs = [c.text for c in chunks]
        metas = [dict(c.metadata) for c in chunks]
        # Fall back to deterministic hashing embeddings when none configured.
        embeds = [self._hasher.embed(c.text).tolist() for c in chunks]
        self._collection.upsert(ids=ids, documents=docs, metadatas=metas, embeddings=embeds)

    def similarity_scores(self, query: str) -> Dict[str, float]:
        qv = self._hasher.embed(query).tolist()
        res = self._collection.query(query_embeddings=[qv], n_results=1000)
        ids = res.get("ids", [[]])[0]
        dists = res.get("distances", [[]])[0]
        # Chroma returns distances; cosine distance -> similarity.
        return {cid: 1.0 - float(d) for cid, d in zip(ids, dists)}

    def get(self, chunk_id: str) -> Optional[StoredChunk]:
        res = self._collection.get(ids=[chunk_id])
        ids = res.get("ids") or []
        if not ids:
            return None
        docs = res.get("documents") or []
        metas = res.get("metadatas") or []
        return StoredChunk(id=ids[0], text=docs[0] if docs else "", metadata=metas[0] or {})

    def all_chunks(self) -> List[StoredChunk]:
        res = self._collection.get(include=["documents", "metadatas"])
        out = []
        for cid, doc, meta in zip(
            res.get("ids") or [],
            res.get("documents") or [],
            res.get("metadatas") or [],
        ):
            out.append(StoredChunk(id=cid, text=doc, metadata=meta or {}))
        return out

    def __len__(self) -> int:
        return self._collection.count()


class HashingEmbeddingFunction:
    """Deterministic bag-of-words hashing embedding (offline fallback)."""

    def __init__(self, dim: int = 512) -> None:
        self.dim = dim

    def embed(self, text: str) -> np.ndarray:
        vec = np.zeros(self.dim, dtype=np.float64)
        for token in tokenize(text):
            vec[hash(token) % self.dim] += 1.0
        norm = np.linalg.norm(vec)
        return vec / norm if norm > 0 else vec


def build_store(config) -> "TfidfVectorStore | ChromaVectorStore":
    """Instantiate the configured vector store backend."""
    if config.backend == "chroma":
        try:
            return ChromaVectorStore(config.chroma_collection, config.chroma_persist_dir)
        except Exception:  # pragma: no cover - fallback for offline envs
            return TfidfVectorStore()
    return TfidfVectorStore()

